-- Aprenda se Divertindo · 60 · Trilha Policial · lote extra 10 (estilo de prova) (100 questões)
-- Rode depois do 59-trilha-policial-9.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":6439,"materia":"pen","nivel":0,"enunciado":"Ana coloca um perfume na bolsa dentro da loja e sai sem pagar, sem ninguém perceber. Ela cometeu:","opcoes":["Furto","Roubo","Estelionato","Apropriação indébita"],"explicacao":"Subtraiu coisa alheia sem violência nem grave ameaça."},{"id":6440,"materia":"pen","nivel":0,"enunciado":"Marcos aponta uma faca para um pedestre e exige o celular. Ele cometeu:","opcoes":["Roubo","Furto","Extorsão","Ameaça"],"explicacao":"Houve subtração com grave ameaça."},{"id":6441,"materia":"pen","nivel":1,"enunciado":"Lia anuncia um carro na internet, recebe o Pix do comprador e desaparece sem entregar nada. Ela cometeu:","opcoes":["Estelionato","Furto mediante fraude","Roubo","Receptação"],"explicacao":"Enganou a vítima para obter vantagem; por ter sido pela internet, é fraude eletrônica (art. 171, § 2º-A)."},{"id":6442,"materia":"pen","nivel":1,"enunciado":"Pedro compra por R$ 200 um celular novo que sabe ter sido roubado. Ele comete:","opcoes":["Receptação","Furto","Roubo","Favorecimento pessoal"],"explicacao":"Art. 180 do Código Penal."},{"id":6443,"materia":"pen","nivel":2,"enunciado":"O motorista que oferece dinheiro ao policial para não ser autuado comete:","opcoes":["Corrupção ativa","Corrupção passiva","Concussão","Tráfico de influência"],"explicacao":"Art. 333: oferecer vantagem indevida a funcionário público."},{"id":6444,"materia":"pen","nivel":1,"enunciado":"Sob a influência do estado puerperal, logo após o parto, a mãe mata o próprio filho. É crime de:","opcoes":["Infanticídio","Homicídio qualificado","Aborto","Homicídio culposo"],"explicacao":"Art. 123 do Código Penal."},{"id":6445,"materia":"pen","nivel":2,"enunciado":"João começa a arrombar uma porta para furtar, mas desiste por vontade própria antes de entrar. Ele responde:","opcoes":["Só pelos atos já praticados, como o dano","Por tentativa de furto qualificado","Por furto consumado, pois já agiu","Por nada, nem mesmo pelo dano"],"explicacao":"Desistência voluntária (art. 15 do Código Penal)."},{"id":6446,"materia":"pen","nivel":3,"enunciado":"Num crime sem violência, o autor devolve tudo por vontade própria antes do recebimento da denúncia. A pena é reduzida de:","opcoes":["1/3 a 2/3","1/6 a 1/3","Metade","1/5 a 1/4"],"explicacao":"Arrependimento posterior (art. 16 do Código Penal)."},{"id":6447,"materia":"pen","nivel":1,"enunciado":"Atacado com uma faca, Paulo empurra o agressor, que cai e se machuca. Paulo agiu em:","opcoes":["Legítima defesa","Estado de necessidade","Exercício regular de direito","Estrito cumprimento do dever legal"],"explicacao":"Repeliu injusta agressão atual, usando moderadamente os meios necessários."},{"id":6448,"materia":"pen","nivel":3,"enunciado":"Um caçador atira no que pensa ser um animal na mata, mas era uma pessoa. Se o erro era inevitável:","opcoes":["Excluem-se o dolo e a culpa","Responde por homicídio doloso","Responde por homicídio culposo","Tem apenas a pena reduzida"],"explicacao":"Erro de tipo inevitável (art. 20 do Código Penal)."},{"id":6449,"materia":"pen","nivel":4,"enunciado":"O policial em serviço que assiste a um estupro sem intervir, podendo agir, responde:","opcoes":["Pelo próprio estupro, por omissão imprópria","Só por prevaricação, por deixar de agir","Por omissão de socorro à vítima","Por condescendência criminosa"],"explicacao":"Quem tem o dever de agir é garantidor (art. 13, § 2º, do Código Penal)."},{"id":6450,"materia":"pen","nivel":3,"enunciado":"Pegar um carro alheio só para dar uma volta e devolvê-lo intacto logo depois é, em regra:","opcoes":["Fato atípico (furto de uso)","Furto simples consumado","Roubo, pela falta de autorização","Apropriação indébita"],"explicacao":"Falta a intenção de ficar com a coisa para si."},{"id":6451,"materia":"pen","nivel":3,"enunciado":"Desde a Lei 14.994/2024, o feminicídio é:","opcoes":["Crime autônomo, com pena de 20 a 40 anos","Qualificadora do homicídio, com pena de 12 a 30 anos","Homicídio privilegiado","Contravenção penal"],"explicacao":"Art. 121-A do Código Penal."},{"id":6452,"materia":"pen","nivel":2,"enunciado":"Dar causa a investigação policial contra alguém que se sabe inocente é:","opcoes":["Denunciação caluniosa","Calúnia","Falso testemunho","Comunicação falsa de crime"],"explicacao":"Art. 339 do Código Penal."},{"id":6453,"materia":"pen","nivel":2,"enunciado":"Avisar a polícia de um crime que se sabe que não aconteceu, sem apontar autor, é:","opcoes":["Comunicação falsa de crime","Denunciação caluniosa","Calúnia","Fraude processual"],"explicacao":"Art. 340 do Código Penal."},{"id":6454,"materia":"pen","nivel":0,"enunciado":"Quem mata alguém de propósito comete homicídio:","opcoes":["Doloso","Culposo","Preterdoloso","Privilegiado"],"explicacao":"Há intenção de matar ou se assume o risco."},{"id":6455,"materia":"ppen","nivel":0,"enunciado":"Quem preside o inquérito policial é o:","opcoes":["Delegado de polícia","Juiz","Promotor de Justiça","Escrivão"],"explicacao":"Lei 12.830/2013."},{"id":6456,"materia":"ppen","nivel":1,"enunciado":"José é preso enquanto arrombava um carro. Esse flagrante é:","opcoes":["Próprio","Impróprio","Presumido","Diferido"],"explicacao":"Art. 302, I, do CPP: está cometendo a infração."},{"id":6457,"materia":"ppen","nivel":2,"enunciado":"O ladrão é perseguido logo após o crime, sem interrupção, e preso horas depois. Esse flagrante é:","opcoes":["Impróprio","Próprio","Presumido","Preparado"],"explicacao":"Art. 302, III, do CPP."},{"id":6458,"materia":"ppen","nivel":2,"enunciado":"O suspeito é encontrado logo depois do crime com a arma e os objetos roubados. Esse flagrante é:","opcoes":["Presumido","Próprio","Impróprio","Esperado"],"explicacao":"Art. 302, IV, do CPP."},{"id":6459,"materia":"ppen","nivel":3,"enunciado":"O flagrante preparado, em que o policial induz alguém a cometer o crime para prendê-lo:","opcoes":["Não vale: o crime é impossível (Súmula 145)","É válido em qualquer caso, como prova","É o mesmo que o flagrante esperado","Só vale com ordem do juiz"],"explicacao":"No flagrante esperado, a polícia só aguarda, sem provocar."},{"id":6460,"materia":"ppen","nivel":3,"enunciado":"Na Lei de Organizações Criminosas, a ação controlada, que retarda a prisão para colher mais provas, deve ser:","opcoes":["Comunicada antes ao juiz","Autorizada pelo governador","Aprovada pelo investigado","Feita sem qualquer controle"],"explicacao":"Art. 8º, § 1º, da Lei 12.850/2013."},{"id":6461,"materia":"ppen","nivel":1,"enunciado":"A audiência de custódia deve ocorrer em até:","opcoes":["24 horas após a prisão","72 horas após a prisão","5 dias úteis","10 dias"],"explicacao":"Art. 310 do CPP."},{"id":6462,"materia":"ppen","nivel":4,"enunciado":"No inquérito da Polícia Federal com investigado preso, o prazo é de:","opcoes":["15 dias, prorrogáveis por mais 15","10 dias, sem prorrogação possível","30 dias, prorrogáveis por mais 30","5 dias"],"explicacao":"Art. 66 da Lei 5.010/1966."},{"id":6463,"materia":"ppen","nivel":2,"enunciado":"O advogado tem direito de acessar, no inquérito, as provas:","opcoes":["Já documentadas nos autos (Súmula Vinculante 14)","Ainda em andamento, como escutas em curso","Somente depois da denúncia","Somente com ordem do juiz"],"explicacao":"Diligências em andamento podem ficar sob sigilo."},{"id":6464,"materia":"ppen","nivel":2,"enunciado":"O indiciamento é ato:","opcoes":["Privativo do delegado, por ato fundamentado","Do juiz, ao receber a denúncia","Do promotor, no oferecimento da denúncia","Do escrivão, ao ouvir o suspeito"],"explicacao":"Art. 2º, § 6º, da Lei 12.830/2013."},{"id":6465,"materia":"ppen","nivel":3,"enunciado":"Pela Lei 12.830/2013, o inquérito só pode ser tirado do delegado:","opcoes":["Por despacho fundamentado do superior hierárquico","Por pedido escrito do próprio investigado","Por decisão do Ministério Público","Livremente, sem motivo"],"explicacao":"Art. 2º, § 4º. Também cabe por desrespeito a procedimentos previstos."},{"id":6466,"materia":"ppen","nivel":3,"enunciado":"Para o STF (Tema 280), a polícia pode entrar numa casa sem mandado quando:","opcoes":["Há fundadas razões de flagrante, justificadas depois","O policial tem apenas uma intuição de que há droga","O morador já tem passagem pela polícia","Já passou da meia-noite"],"explicacao":"Sem fundadas razões, a prova é ilícita e há responsabilização."},{"id":6467,"materia":"ppen","nivel":3,"enunciado":"A interceptação telefônica é autorizada por:","opcoes":["15 dias, renováveis se indispensável","30 dias, sem possibilidade de renovação","60 dias corridos, renováveis uma vez","Prazo indeterminado"],"explicacao":"Art. 5º da Lei 9.296/1996."},{"id":6468,"materia":"ppen","nivel":4,"enunciado":"Não se admite interceptação telefônica quando o crime for punido, no máximo, com pena de:","opcoes":["Detenção","Reclusão","Reclusão e multa","Reclusão acima de 4 anos"],"explicacao":"Art. 2º, III, da Lei 9.296/1996."},{"id":6469,"materia":"ppen","nivel":4,"enunciado":"Para o STJ, o reconhecimento de pessoa feito sem as formalidades do art. 226 do CPP:","opcoes":["Não basta, sozinho, para a condenação","Tem o mesmo valor do feito com o rito","É prova plena se feito na delegacia","Foi expressamente proibido pela lei"],"explicacao":"O rito é garantia mínima; sem ele o reconhecimento é frágil."},{"id":6470,"materia":"leg","nivel":0,"enunciado":"O porte ilegal de arma de fogo é crime previsto:","opcoes":["No Estatuto do Desarmamento","Na Lei de Drogas e Afins","No Código de Trânsito","Na Lei Maria da Penha"],"explicacao":"Lei 10.826/2003."},{"id":6471,"materia":"leg","nivel":0,"enunciado":"Dirigir embriagado é crime previsto:","opcoes":["No Código de Trânsito Brasileiro","Na Lei de Drogas","No ECA","No Estatuto do Desarmamento"],"explicacao":"Art. 306 do CTB."},{"id":6472,"materia":"leg","nivel":1,"enunciado":"Quem é flagrado com pequena quantidade de droga para consumo próprio:","opcoes":["Não é preso: assina termo e recebe medidas educativas","É preso em flagrante por tráfico de drogas","Paga fiança na delegacia e é liberado","Vai a júri popular"],"explicacao":"Art. 28 da Lei de Drogas."},{"id":6473,"materia":"leg","nivel":4,"enunciado":"Pelo STF (2024), presume-se usuário quem porta maconha até:","opcoes":["40 gramas ou 6 plantas fêmeas","100 gramas ou 10 plantas","10 gramas ou 1 planta","1 quilo"],"explicacao":"A presunção é relativa: outros indícios podem apontar tráfico."},{"id":6474,"materia":"leg","nivel":2,"enunciado":"Nos crimes de violência doméstica contra a mulher, é proibido aplicar:","opcoes":["Pena de cesta básica ou só multa","Prisão preventiva do agressor","Medida protetiva de urgência","Inquérito policial"],"explicacao":"Art. 17 da Lei Maria da Penha."},{"id":6475,"materia":"leg","nivel":3,"enunciado":"A lesão corporal leve contra a mulher em violência doméstica é de ação penal:","opcoes":["Pública incondicionada","Condicionada à representação","Privada","Condicionada à requisição"],"explicacao":"Súmula 542 do STJ."},{"id":6476,"materia":"leg","nivel":4,"enunciado":"O porte ilegal de arma de uso permitido (art. 14 do Estatuto do Desarmamento) é afiançável?","opcoes":["Sim; o STF derrubou a vedação da fiança","Não, é inafiançável por lei","Só por decisão do juiz","Só se a arma estiver descarregada"],"explicacao":"ADI 3.112: declarada inconstitucional a inafiançabilidade."},{"id":6477,"materia":"leg","nivel":3,"enunciado":"Portar arma com a numeração raspada é crime:","opcoes":["Do art. 16, como o de uso restrito","Do art. 12, de posse irregular","Do art. 14, de porte de uso permitido","De contravenção penal"],"explicacao":"Art. 16, § 1º, IV, do Estatuto do Desarmamento."},{"id":6478,"materia":"leg","nivel":1,"enunciado":"O homicídio qualificado é crime hediondo?","opcoes":["Sim","Não","Só se for contra policial","Só se for tentado"],"explicacao":"Art. 1º, I, da Lei 8.072/1990."},{"id":6479,"materia":"leg","nivel":3,"enunciado":"O condenado primário por crime hediondo sem morte progride de regime após cumprir:","opcoes":["40% da pena","1/6 da pena","25% da pena","70% da pena"],"explicacao":"Art. 112, V, da LEP, com o Pacote Anticrime."},{"id":6480,"materia":"leg","nivel":4,"enunciado":"O condenado primário por crime hediondo com resultado morte progride após cumprir:","opcoes":["50% da pena, sem livramento condicional","40% da pena, com direito a livramento","30% da pena, com livramento","70% da pena"],"explicacao":"Art. 112, VI, a, da LEP."},{"id":6481,"materia":"leg","nivel":3,"enunciado":"Na Lei de Abuso de Autoridade, só há crime se o agente agir com a finalidade de:","opcoes":["Prejudicar outrem, beneficiar-se ou por capricho","Cumprir o dever legal com rigor","Proteger a vítima de nova agressão","Evitar um crime maior"],"explicacao":"Art. 1º, § 1º, da Lei 13.869/2019."},{"id":6482,"materia":"leg","nivel":3,"enunciado":"Na Lei de Abuso de Autoridade, divergir na interpretação da lei ou na avaliação das provas:","opcoes":["Não é, por si só, abuso de autoridade","É sempre crime de abuso de autoridade","Gera perda automática do cargo","Permite prisão em flagrante"],"explicacao":"Art. 1º, § 2º, da Lei 13.869/2019."},{"id":6483,"materia":"leg","nivel":0,"enunciado":"Pelo ECA, é criança quem tem até:","opcoes":["12 anos incompletos","14 anos incompletos","16 anos incompletos","18 anos incompletos"],"explicacao":"Adolescente: de 12 a 18 anos."},{"id":6484,"materia":"leg","nivel":1,"enunciado":"O adolescente apreendido em flagrante de ato infracional deve ser levado:","opcoes":["À autoridade policial competente","Direto a um presídio comum","Ao Conselho Tutelar, sem registro","A um quartel do Exército"],"explicacao":"Art. 172 do ECA."},{"id":6485,"materia":"leg","nivel":3,"enunciado":"Pelo ECA, a liberação do internado é compulsória aos:","opcoes":["21 anos","18 anos","24 anos","25 anos"],"explicacao":"Art. 121, § 5º, do ECA."},{"id":6486,"materia":"leg","nivel":1,"enunciado":"A associação criminosa do Código Penal (art. 288) exige pelo menos:","opcoes":["3 pessoas","4 pessoas","2 pessoas","10 pessoas"],"explicacao":"A organização criminosa da Lei 12.850 exige 4 ou mais."},{"id":6487,"materia":"leg","nivel":3,"enunciado":"Na colaboração premiada, o juiz participa das negociações do acordo?","opcoes":["Não; ele só analisa o acordo depois","Sim, ele preside as negociações","Sim, ele propõe os benefícios","Só em crimes hediondos"],"explicacao":"Art. 4º, § 6º, da Lei 12.850/2013."},{"id":6488,"materia":"leg","nivel":4,"enunciado":"A infiltração de agentes na Lei de Organizações Criminosas é autorizada por até:","opcoes":["6 meses, renováveis","30 dias, sem renovação","1 ano, improrrogável","2 anos"],"explicacao":"Art. 10, § 3º, da Lei 12.850/2013."},{"id":6489,"materia":"leg","nivel":1,"enunciado":"Pelo Código de Trânsito, recusar o teste do bafômetro gera:","opcoes":["Multa e suspensão do direito de dirigir","Prisão em flagrante automática do motorista","Nenhuma consequência legal","Apenas advertência verbal"],"explicacao":"Art. 165-A do CTB."},{"id":6490,"materia":"leg","nivel":4,"enunciado":"O homicídio culposo na direção de veículo, com o motorista sob efeito de álcool, tem pena de:","opcoes":["Reclusão de 5 a 8 anos","Detenção de 2 a 4 anos","Detenção de 6 meses a 1 ano","Reclusão de 12 a 30 anos"],"explicacao":"Art. 302, § 3º, do CTB."},{"id":6491,"materia":"leg","nivel":1,"enunciado":"Abandonar pessoa idosa em hospital ou casa de saúde é crime?","opcoes":["Sim, previsto no Estatuto da Pessoa Idosa","Não, é apenas uma falta moral da família","Só se a pessoa idosa morrer","Só se o autor for filho"],"explicacao":"Art. 98 da Lei 10.741/2003."},{"id":6492,"materia":"const","nivel":0,"enunciado":"O remédio constitucional que protege o direito de ir e vir é o:","opcoes":["Habeas corpus","Habeas data","Mandado de injunção","Ação popular"],"explicacao":"Art. 5º, LXVIII, da Constituição."},{"id":6493,"materia":"const","nivel":0,"enunciado":"Pela Constituição, o preso deve ser informado dos seus direitos, entre eles o de:","opcoes":["Permanecer calado","Escolher a cela","Sair quando quiser","Não ser identificado"],"explicacao":"Art. 5º, LXIII."},{"id":6494,"materia":"const","nivel":4,"enunciado":"São inafiançáveis e imprescritíveis, pela Constituição:","opcoes":["O racismo e a ação de grupos armados contra o Estado","A tortura e o tráfico de drogas","Todos os crimes hediondos e equiparados","O homicídio e o latrocínio"],"explicacao":"Art. 5º, XLII e XLIV."},{"id":6495,"materia":"const","nivel":3,"enunciado":"São inafiançáveis e insuscetíveis de graça ou anistia, pela Constituição:","opcoes":["Tortura, tráfico, terrorismo e hediondos","Racismo e injúria racial","Ação de grupos armados","Furto e roubo qualificados"],"explicacao":"Art. 5º, XLIII. Esses não são imprescritíveis."},{"id":6496,"materia":"const","nivel":3,"enunciado":"Para o STF (ADPF 995), as guardas municipais:","opcoes":["Integram o Sistema de Segurança Pública","São apenas vigias de prédios municipais","Fazem parte do Poder Judiciário local","Integram as Forças Armadas"],"explicacao":"Elas não substituem as polícias, mas atuam na segurança urbana."},{"id":6497,"materia":"const","nivel":1,"enunciado":"O brasileiro nato pode ser extraditado?","opcoes":["Não, nunca","Sim, por tráfico de drogas","Sim, por crime comum","Sim, se o STF autorizar"],"explicacao":"Art. 5º, LI, da Constituição."},{"id":6498,"materia":"const","nivel":4,"enunciado":"O brasileiro naturalizado pode ser extraditado por:","opcoes":["Crime comum antes da naturalização ou tráfico comprovado","Qualquer crime, cometido a qualquer tempo","Crime político ou de opinião, em qualquer caso","Nenhum crime, como o nato"],"explicacao":"Art. 5º, LI, da Constituição."},{"id":6499,"materia":"adm","nivel":0,"enunciado":"Os princípios da administração pública no art. 37 da Constituição formam a sigla:","opcoes":["LIMPE","SUSP","CLT","ECA"],"explicacao":"Legalidade, impessoalidade, moralidade, publicidade e eficiência."},{"id":6500,"materia":"adm","nivel":1,"enunciado":"O policial que usa a viatura para levar a família à praia fere, sobretudo, o princípio da:","opcoes":["Moralidade","Publicidade","Eficiência","Anterioridade"],"explicacao":"Usa o bem público em proveito particular."},{"id":6501,"materia":"adm","nivel":2,"enunciado":"O agente que atua fora dos limites da sua competência pratica abuso de poder na forma de:","opcoes":["Excesso de poder","Desvio de finalidade","Omissão","Ato vinculado"],"explicacao":"No desvio, o agente é competente, mas busca outro fim."},{"id":6502,"materia":"adm","nivel":2,"enunciado":"O chefe remove um servidor para outra cidade só para puni-lo. Isso é:","opcoes":["Desvio de finalidade","Excesso de poder","Ato vinculado regular","Revogação por conveniência"],"explicacao":"Remoção não é instrumento de punição."},{"id":6503,"materia":"adm","nivel":2,"enunciado":"O ato administrativo ilegal deve ser:","opcoes":["Anulado, com efeitos retroativos","Revogado por conveniência","Mantido, por segurança jurídica","Convalidado em todos os casos"],"explicacao":"A revogação atinge atos válidos, por conveniência e oportunidade."},{"id":6504,"materia":"adm","nivel":4,"enunciado":"Pela Lei 9.784/1999, a Administração pode anular atos ilegais que beneficiam o destinatário em até:","opcoes":["5 anos, salvo má-fé","2 anos, em qualquer caso","10 anos, salvo má-fé","Qualquer prazo"],"explicacao":"Art. 54 da Lei 9.784/1999."},{"id":6505,"materia":"adm","nivel":4,"enunciado":"O servidor absolvido na esfera penal por inexistência do fato:","opcoes":["Não pode ser punido administrativamente pelo fato","Pode ser punido normalmente no processo disciplinar","Só é absolvido também na esfera cível","Deve ser demitido"],"explicacao":"Art. 126 da Lei 8.112/1990. Absolvição por falta de provas não tem esse efeito."},{"id":6506,"materia":"dh","nivel":0,"enunciado":"A Constituição diz que ninguém será submetido a tortura nem a tratamento:","opcoes":["Desumano ou degradante","Médico sem consentimento","Judicial","Educativo"],"explicacao":"Art. 5º, III."},{"id":6507,"materia":"dh","nivel":2,"enunciado":"Pelos Princípios Básicos da ONU sobre Uso da Força e Armas de Fogo, o policial só deve usar arma de fogo:","opcoes":["Contra ameaça iminente de morte ou ferimento grave","Diante de qualquer fuga de suspeito","Contra quem desobedece à ordem de parar","Contra ofensas verbais"],"explicacao":"O uso letal intencional só é aceito quando inevitável para proteger a vida."},{"id":6508,"materia":"dh","nivel":3,"enunciado":"Para o STF, a prisão civil do depositário infiel:","opcoes":["É ilícita (Súmula Vinculante 25)","É permitida por até 1 ano","Só vale para estrangeiros","Dura até 30 dias"],"explicacao":"Só subsiste a prisão civil do devedor de alimentos."},{"id":6509,"materia":"dh","nivel":3,"enunciado":"Tratado de direitos humanos aprovado sem o rito de emenda tem, para o STF, status:","opcoes":["Supralegal","Constitucional","De lei complementar","De decreto"],"explicacao":"Fica abaixo da Constituição e acima das leis."},{"id":6510,"materia":"dh","nivel":4,"enunciado":"O deslocamento de grave violação de direitos humanos para a Justiça Federal é pedido:","opcoes":["Pelo Procurador-Geral da República ao STJ","Pelo delegado de polícia ao STF","Pelo governador do estado ao STF","Pela vítima ao juiz federal"],"explicacao":"Incidente de deslocamento de competência (art. 109, § 5º)."},{"id":6511,"materia":"inf","nivel":1,"enunciado":"Programa disfarçado de aplicativo legítimo que abre acesso ao invasor é o:","opcoes":["Cavalo de Troia","Worm","Spam","Cookie de sessão"],"explicacao":"Também chamado de trojan."},{"id":6512,"materia":"inf","nivel":0,"enunciado":"O ransomware:","opcoes":["Sequestra os dados e pede resgate","Acelera o processamento do computador","É um tipo de antivírus gratuito","É um navegador de internet"],"explicacao":"Costuma criptografar os arquivos da vítima."},{"id":6513,"materia":"inf","nivel":0,"enunciado":"A autenticação em dois fatores combina, por exemplo:","opcoes":["Senha e código enviado ao celular","Duas senhas iguais digitadas","Login e endereço de e-mail","Nome e sobrenome"],"explicacao":"Une algo que você sabe com algo que você tem."},{"id":6514,"materia":"inf","nivel":0,"enunciado":"No Excel, se A1, A2 e A3 valem 2, 4 e 6, a fórmula =SOMA(A1:A3) dá:","opcoes":["12","6","3","246"],"explicacao":"2 + 4 + 6 = 12."},{"id":6515,"materia":"inf","nivel":1,"enunciado":"No Excel, se B1 a B4 valem 2, 4, 6 e 8, a fórmula =MÉDIA(B1:B4) dá:","opcoes":["5","4","20","8"],"explicacao":"20 ÷ 4 = 5."},{"id":6516,"materia":"inf","nivel":2,"enunciado":"No Excel, com A1 = 6,9, a fórmula =SE(A1>=7;\"Aprovado\";\"Reprovado\") mostra:","opcoes":["Reprovado","Aprovado","6,9","Erro"],"explicacao":"6,9 é menor que 7."},{"id":6517,"materia":"inf","nivel":3,"enunciado":"Em perícia digital, calcular o hash (como SHA-256) de uma evidência serve para:","opcoes":["Provar que ela não foi alterada","Esconder o conteúdo do arquivo","Diminuir o tamanho do arquivo","Apagar rastros do suspeito"],"explicacao":"Qualquer mudança no arquivo muda o hash."},{"id":6518,"materia":"rl","nivel":0,"enunciado":"Uma viatura anda a 60 km/h durante 3 horas. Ela percorre:","opcoes":["180 km","120 km","63 km","200 km"],"explicacao":"60 × 3 = 180."},{"id":6519,"materia":"rl","nivel":0,"enunciado":"48 policiais serão divididos em 6 equipes iguais. Cada equipe terá:","opcoes":["8","6","7","9"],"explicacao":"48 ÷ 6 = 8."},{"id":6520,"materia":"rl","nivel":0,"enunciado":"De 320 apreensões, 25% foram de drogas. Quantas foram de drogas?","opcoes":["80","25","32","64"],"explicacao":"320 ÷ 4 = 80."},{"id":6521,"materia":"rl","nivel":0,"enunciado":"Na sequência 3, 6, 12, 24, ..., o próximo número é:","opcoes":["48","30","36","42"],"explicacao":"Cada termo é o dobro do anterior."},{"id":6522,"materia":"rl","nivel":2,"enunciado":"Nenhum policial é covarde, e alguns soldados são policiais. Logo:","opcoes":["Alguns soldados não são covardes","Nenhum soldado é covarde","Todo soldado é policial","Todo covarde é soldado"],"explicacao":"Os soldados que são policiais não são covardes."},{"id":6523,"materia":"rl","nivel":1,"enunciado":"Lançando uma moeda duas vezes, a probabilidade de dar cara nas duas é:","opcoes":["1/4","1/2","1/3","3/4"],"explicacao":"1/2 × 1/2."},{"id":6524,"materia":"rl","nivel":3,"enunciado":"De quantas formas se escolhe uma comissão de 3 agentes entre 8?","opcoes":["56","336","24","512"],"explicacao":"C(8,3) = 8 × 7 × 6 ÷ 6 = 56."},{"id":6525,"materia":"rl","nivel":2,"enunciado":"R$ 2.000 aplicados a juros simples de 5% ao mês, por 4 meses, rendem de juros:","opcoes":["R$ 400","R$ 100","R$ 431","R$ 2.400"],"explicacao":"2.000 × 0,05 × 4 = 400."},{"id":6526,"materia":"est","nivel":0,"enunciado":"A moda do conjunto 3, 5, 5, 7, 9 é:","opcoes":["5","3","7","9"],"explicacao":"É o valor que mais se repete."},{"id":6527,"materia":"est","nivel":1,"enunciado":"A mediana de 2, 8, 4, 10, 6 é:","opcoes":["6","4","8","5"],"explicacao":"Em ordem (2, 4, 6, 8, 10), o valor do meio é 6."},{"id":6528,"materia":"cont","nivel":1,"enunciado":"Uma entidade tem ativo de R$ 100 mil e passivo de R$ 60 mil. O patrimônio líquido é:","opcoes":["R$ 40 mil","R$ 160 mil","R$ 60 mil","R$ 100 mil"],"explicacao":"PL = ativo − passivo."},{"id":6529,"materia":"ml","nivel":3,"enunciado":"As manchas de hipóstase (livores) costumam se fixar cerca de:","opcoes":["12 horas após a morte","1 hora após a morte","3 dias após a morte","1 semana após a morte"],"explicacao":"Antes disso, mudam de lugar se o corpo for movido."},{"id":6530,"materia":"ml","nivel":3,"enunciado":"Num tiro a curta distância, a ferida de entrada costuma ter:","opcoes":["Zona de tatuagem e esfumaçamento","Bordas viradas para fora, sem orla","Nenhuma marca ao redor","Forma de casa de botão"],"explicacao":"Grãos de pólvora e fuligem atingem a pele."},{"id":6531,"materia":"ml","nivel":1,"enunciado":"Instrumento cortante, como uma navalha, produz ferida:","opcoes":["Incisa","Contusa","Perfurante","Lacerocontusa"],"explicacao":"Bordas regulares, mais longa que profunda."},{"id":6532,"materia":"ml","nivel":2,"enunciado":"Asfixia em que o laço aperta o pescoço pelo próprio peso do corpo é o:","opcoes":["Enforcamento","Estrangulamento","Esganadura","Sufocação"],"explicacao":"No estrangulamento, a força é de outra fonte; na esganadura, das mãos."},{"id":6533,"materia":"ml","nivel":0,"enunciado":"A identificação de uma pessoa pelas impressões digitais chama-se:","opcoes":["Papiloscopia","Odontologia","Toxicologia","Balística"],"explicacao":"A datiloscopia é o ramo das digitais dos dedos."},{"id":6534,"materia":"port","nivel":1,"enunciado":"Assinale a frase correta:","opcoes":["Faz dois anos que entrei na polícia","Fazem dois anos que entrei na polícia","Fazem-se dois anos que entrei na polícia","Fizeram dois anos que entrei na polícia"],"explicacao":"\"Fazer\" indicando tempo é impessoal: fica no singular."},{"id":6535,"materia":"port","nivel":0,"enunciado":"Complete: \"O suspeito foi levado ___ delegacia.\"","opcoes":["à","a","há","ah"],"explicacao":"Levar a + a delegacia = à."},{"id":6536,"materia":"port","nivel":1,"enunciado":"A forma correta é:","opcoes":["Houve muitos crimes no bairro","Houveram muitos crimes no bairro","Houveram-se muitos crimes no bairro","Ouve muitos crimes no bairro"],"explicacao":"\"Haver\" no sentido de existir é impessoal."},{"id":6537,"materia":"port","nivel":1,"enunciado":"Complete: \"O depoimento foi ___ redigido.\"","opcoes":["mal","mau","mais","mas"],"explicacao":"\"Mal\" é o contrário de \"bem\"; \"mau\", de \"bom\"."},{"id":6538,"materia":"port","nivel":3,"enunciado":"No sentido de almejar, a frase correta é:","opcoes":["O agente visava à promoção","O agente visava a promoção","O agente visava em promoção","O agente visava pela promoção"],"explicacao":"\"Visar\" no sentido de almejar pede a preposição \"a\"."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
